package com.civicpulse.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="complaints",indexes={@Index(name="idx_complaint_status",columnList="status"),@Index(name="idx_complaint_location",columnList="latitude,longitude")}) @Getter @Setter @NoArgsConstructor
public class Complaint { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID complaintId; @ManyToOne(optional=false) @JoinColumn(name="citizen_id") private User citizen; @ManyToOne @JoinColumn(name="department_id") private Department department; @ManyToOne(optional=false) @JoinColumn(name="category_id") private Category category; @Column(nullable=false) private String title; @Column(nullable=false,columnDefinition="TEXT") private String description; private Double latitude; private Double longitude; private String address; @Enumerated(EnumType.STRING) @Column(nullable=false) private Priority priority=Priority.MEDIUM; @Enumerated(EnumType.STRING) @Column(nullable=false) private ComplaintStatus status=ComplaintStatus.REPORTED; private Instant dueAt; @Column(nullable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now(); }
